-- 세트 370: 링크와 파일 비교 손에 익히기: ln -s·ln, readlink, stat -c %h, diff·diff -u, patch, cmp -s
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_linux_links_diff_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (370, 1, '심볼릭 링크 만들기 (ln -s)', '**배경** — 링크는 파일에 다른 이름으로 접근하게 해 주는 것입니다. **심볼릭(소프트) 링크** 는 "다른 경로를 가리키는 바로가기" 파일이고, `ln -s 가리킬대상 링크이름` 으로 만듭니다. 이 세트의 문제는 `/tmp/lab` 안의 연습 파일을 씁니다 (`app/` 에 설정 파일, `data/` 에 목록·메모 파일). 문제마다 처음 상태에서 다시 시작합니다.

**문제** — `/tmp/lab/current.conf` 라는 **심볼릭 링크** 를 만들어, `/tmp/lab/app/config.txt` 를 **절대 경로로** 가리키게 하세요.', '`ln -s` 의 첫 인자가 **가리킬 대상**, 두 번째가 **새 링크 이름** 입니다. `ls -l` 로 `->` 표시를 확인할 수 있습니다.', 'ln -s /tmp/lab/app/config.txt /tmp/lab/current.conf
ls -l /tmp/lab/current.conf

# ln -s 대상 링크이름. ls -l 에 current.conf -> /tmp/lab/app/config.txt 로 보인다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ -L /tmp/lab/current.conf ] ) && ( [ \\"$(readlink /tmp/lab/current.conf)\\" = /tmp/lab/app/config.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "current.conf 가 심볼릭 링크다", "cmd": ["sh", "-c", "[ -L /tmp/lab/current.conf ]"]}, {"label": "가리키는 곳이 /tmp/lab/app/config.txt 다", "cmd": ["sh", "-c", "[ \\"$(readlink /tmp/lab/current.conf)\\" = /tmp/lab/app/config.txt ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 2, '링크가 가리키는 곳 읽기 (readlink)', '`/tmp/lab/latest` 는 심볼릭 링크입니다. 이 링크가 **가리키는 경로 글자 그대로** 를 출력해 **`/tmp/q2.txt`** 에 저장하세요.', '`ls -l` 로도 `->` 뒤에서 볼 수 있지만, 경로만 깔끔히 얻으려면 `readlink 링크` 를 쓰세요.', 'readlink /tmp/lab/latest > /tmp/q2.txt
cat /tmp/q2.txt

# readlink 는 링크가 가리키는 경로를 그대로 출력한다 (상대 경로면 상대 경로 그대로)', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ \\"$(cat /tmp/q2.txt)\\" = \\"$(readlink /tmp/lab/latest)\\" ] ) && ( [ \\"$(cat /tmp/q2.txt)\\" = app/config.new ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 링크의 대상 경로와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q2.txt)\\" = \\"$(readlink /tmp/lab/latest)\\" ]"]}, {"label": "app/config.new 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q2.txt)\\" = app/config.new ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 3, '하드 링크 만들기 (ln)', '**배경** — **하드 링크** 는 같은 파일(같은 inode)에 이름을 하나 더 붙이는 것입니다. 심볼릭 링크와 달리 경로가 아니라 파일 자체를 가리키며, `-s` 없이 `ln 원본 새이름` 으로 만듭니다.

**문제** — `/tmp/lab/data/list.txt` 의 **하드 링크** `/tmp/lab/data/list.hard` 를 만드세요.', '`-s` 를 **붙이지 않은** `ln` 이 하드 링크를 만듭니다. `ls -li` 로 inode 번호가 같은지 볼 수 있습니다.', 'ln /tmp/lab/data/list.txt /tmp/lab/data/list.hard
ls -li /tmp/lab/data/list.txt /tmp/lab/data/list.hard

# -s 없는 ln 은 하드 링크. ls -li 에서 두 이름의 inode 번호가 같다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ -f /tmp/lab/data/list.hard ] && [ ! -L /tmp/lab/data/list.hard ] ) && ( [ \\"$(stat -c %i /tmp/lab/data/list.txt)\\" = \\"$(stat -c %i /tmp/lab/data/list.hard)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "list.hard 가 있고 심볼릭 링크가 아니다", "cmd": ["sh", "-c", "[ -f /tmp/lab/data/list.hard ] && [ ! -L /tmp/lab/data/list.hard ]"]}, {"label": "list.txt 와 inode 가 같다", "cmd": ["sh", "-c", "[ \\"$(stat -c %i /tmp/lab/data/list.txt)\\" = \\"$(stat -c %i /tmp/lab/data/list.hard)\\" ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 4, '하드 링크 개수 확인하기', '`/tmp/lab/data/shared.txt` 는 이미 이름이 여러 개일 수 있습니다. 이 파일의 **하드 링크 개수** 를 숫자 하나로 출력해 **`/tmp/q4.txt`** 에 저장하세요.', '`ls -l` 의 둘째 칸 숫자가 링크 개수입니다. `stat -c 형식` 으로 필요한 값만 뽑을 수도 있습니다 (`%h`).', 'stat -c %h /tmp/lab/data/shared.txt > /tmp/q4.txt
cat /tmp/q4.txt

# stat -c %h 는 하드 링크 개수를 숫자로 출력한다 (ls -l 의 둘째 칸과 같다)', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ \\"$(cat /tmp/q4.txt)\\" = \\"$(stat -c %h /tmp/lab/data/shared.txt)\\" ] ) && ( [ \\"$(cat /tmp/q4.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 가 실제 링크 개수와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q4.txt)\\" = \\"$(stat -c %h /tmp/lab/data/shared.txt)\\" ]"]}, {"label": "개수는 2 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q4.txt)\\" = 2 ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 5, '원본을 지우면 링크는? (하드 vs 심볼릭)', '`/tmp/lab/data/` 에는 원본 `orig.txt`, 그 **하드 링크** `hard.txt`, **심볼릭 링크** `soft.txt` 가 있습니다. 원본 `orig.txt` 를 **삭제** 한 뒤, `hard.txt` 의 내용을 **`/tmp/q5.txt`** 에 저장하세요.', '이름 하나를 지워도 같은 파일에 이름이 남아 있으면 내용은 사라지지 않습니다. `soft.txt` 가 어떻게 되는지도 `ls -l` 로 보세요.', 'rm /tmp/lab/data/orig.txt
cat /tmp/lab/data/hard.txt > /tmp/q5.txt
ls -l /tmp/lab/data

# 원본을 지워도 하드 링크는 내용을 그대로 갖고, 심볼릭 링크 soft.txt 는 가리키는 곳이 없어 끊어진다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ ! -e /tmp/lab/data/orig.txt ] ) && ( [ \\"$(cat /tmp/q5.txt)\\" = hello ] ) && ( [ -L /tmp/lab/data/soft.txt ] && [ ! -e /tmp/lab/data/soft.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "orig.txt 가 지워졌다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/data/orig.txt ]"]}, {"label": "q5.txt 에 hard.txt 의 내용(hello)이 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q5.txt)\\" = hello ]"]}, {"label": "soft.txt 는 끊어진 링크로 남아 있다", "cmd": ["sh", "-c", "[ -L /tmp/lab/data/soft.txt ] && [ ! -e /tmp/lab/data/soft.txt ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 6, '두 파일의 다른 줄 보기 (diff)', '**배경** — `diff 파일1 파일2` 는 두 텍스트 파일이 **어느 줄에서 다른지** 알려 줍니다. `<` 는 첫 번째 파일, `>` 는 두 번째 파일의 줄입니다. 같으면 아무것도 출력하지 않습니다.

**문제** — `/tmp/lab/data/list.txt` 와 `/tmp/lab/data/list.other` 를 **이 순서로** 비교한 결과를 **`/tmp/q6.txt`** 에 저장하세요.', '`diff 앞파일 뒷파일 > 결과파일` 입니다. 파일이 다르면 diff 의 종료 코드는 1 인데, 오류가 아니라 "다르다"는 뜻입니다.', 'diff /tmp/lab/data/list.txt /tmp/lab/data/list.other > /tmp/q6.txt
cat /tmp/q6.txt

# diff 앞파일 뒷파일. < 는 앞 파일, > 는 뒤 파일의 줄이다. 다르면 종료 코드가 1 이다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] && [ \\"$(cat /tmp/q6.txt)\\" = \\"$(diff /tmp/lab/data/list.txt /tmp/lab/data/list.other)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q6.txt 가 두 파일의 diff 출력과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ] && [ \\"$(cat /tmp/q6.txt)\\" = \\"$(diff /tmp/lab/data/list.txt /tmp/lab/data/list.other)\\" ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 7, '패치 파일 만들기 (diff -u)', '**배경** — `diff -u` 는 변경 내용을 **통합(unified) 형식** 으로 출력합니다. 이 출력을 파일로 저장해 두면 `patch` 가 다른 곳에 같은 변경을 적용할 수 있어서 "패치 파일" 이라고 부릅니다.

**문제** — `/tmp/lab/app/config.txt`(옛 설정)를 `/tmp/lab/app/config.new`(새 설정)로 바꾸는 패치를 **`/tmp/q7.patch`** 에 저장하세요. (옛 파일이 앞, 새 파일이 뒤)', '`diff -u 옛파일 새파일 > 패치파일` 입니다. 패치 첫 줄의 `---` 가 옛 파일, `+++` 가 새 파일입니다.', 'diff -u /tmp/lab/app/config.txt /tmp/lab/app/config.new > /tmp/q7.patch
cat /tmp/q7.patch

# diff -u 옛파일 새파일 > 패치. 파일명 헤더(---, +++)와 변경 줄(+, -)이 들어간다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( grep -q \\"^--- \\" /tmp/q7.patch && grep -q \\"^+++ \\" /tmp/q7.patch ) && ( cp /tmp/lab/app/config.txt /tmp/chk7.txt && patch -s /tmp/chk7.txt < /tmp/q7.patch && cmp -s /tmp/chk7.txt /tmp/lab/app/config.new )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "패치 헤더가 있다", "cmd": ["sh", "-c", "grep -q \\"^--- \\" /tmp/q7.patch && grep -q \\"^+++ \\" /tmp/q7.patch"]}, {"label": "옛 설정에 패치를 적용하면 새 설정과 같아진다", "cmd": ["sh", "-c", "cp /tmp/lab/app/config.txt /tmp/chk7.txt && patch -s /tmp/chk7.txt < /tmp/q7.patch && cmp -s /tmp/chk7.txt /tmp/lab/app/config.new"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 8, '패치 적용하기 (patch)', '`/tmp/lab/config.patch` 는 `app/config.txt` 를 새 설정으로 바꾸는 패치입니다. 이 패치를 **`/tmp/lab/app/config.txt` 에 적용** 해서, 내용이 `/tmp/lab/app/config.new` 와 **같아지게** 하세요. (`config.new` 는 건드리지 마세요.)', '`patch 대상파일 < 패치파일` 형태로 적용합니다. 패치는 대상 파일을 **직접 수정** 합니다.', 'patch /tmp/lab/app/config.txt < /tmp/lab/config.patch
cat /tmp/lab/app/config.txt
cmp /tmp/lab/app/config.txt /tmp/lab/app/config.new && echo 같음

# patch 대상 < 패치. 대상 파일이 패치 내용대로 수정되어 config.new 와 같아진다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( cmp -s /tmp/lab/app/config.txt /tmp/lab/app/config.new ) && ( [ \\"$(cat /tmp/lab/app/config.new)\\" = \\"$(printf \\"port=9090\\\\nmode=prod\\\\ndebug=true\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "config.txt 가 config.new 와 같다", "cmd": ["sh", "-c", "cmp -s /tmp/lab/app/config.txt /tmp/lab/app/config.new"]}, {"label": "config.new 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lab/app/config.new)\\" = \\"$(printf \\"port=9090\\\\nmode=prod\\\\ndebug=true\\")\\" ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 9, '내용이 같은지 조용히 확인하기 (cmp -s)', '`cmp -s 파일1 파일2` 는 아무것도 출력하지 않고 **종료 코드** 로만 답합니다 (같으면 0, 다르면 0 이 아님). 이를 이용해 **두 줄** 을 **`/tmp/q9.txt`** 에 만드세요. 첫 줄은 `list.txt` 와 `list.copy` 를 비교해 같으면 `same`, 다르면 `different`, 둘째 줄은 `list.txt` 와 `list.other` 를 비교해 같으면 `same`, 다르면 `different` 입니다. (모두 `/tmp/lab/data/` 안)', '`cmp -s a b && echo same || echo different` 처럼 `&&`(성공하면) 와 `||`(실패하면) 를 이으면 종료 코드에 따라 출력을 고를 수 있습니다. 두 번 실행한 출력을 한 파일로 모으세요.', '{ cmp -s /tmp/lab/data/list.txt /tmp/lab/data/list.copy && echo same || echo different
  cmp -s /tmp/lab/data/list.txt /tmp/lab/data/list.other && echo same || echo different; } > /tmp/q9.txt
cat /tmp/q9.txt

# cmp -s 는 종료 코드만 돌려준다. && 와 || 로 같음/다름을 글자로 바꿔 모은다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt /tmp/*.patch; mkdir -p /tmp/lab/app /tmp/lab/data && cd /tmp/lab\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > app/config.txt\\nprintf ''port=9090\\\\nmode=prod\\\\ndebug=true\\\\n'' > app/config.new\\nln -s app/config.new latest\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.txt\\nprintf ''alpha\\\\nbeta\\\\ngamma\\\\n'' > data/list.copy\\nprintf ''alpha\\\\nbeta\\\\ndelta\\\\n'' > data/list.other\\nprintf ''shared data\\\\n'' > data/shared.txt; ln data/shared.txt data/shared.bak\\nprintf ''hello\\\\n'' > data/orig.txt; ln data/orig.txt data/hard.txt; ln -s orig.txt data/soft.txt\\n(cd app && diff -u config.txt config.new > ../config.patch; true)"]', '["sh", "-c", "( [ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"same\\\\ndifferent\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 가 same, different 두 줄이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"same\\\\ndifferent\\")\\" ]"]}]', '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 10, '다른 디스크(파일 시스템)의 파일을 가리키려면?', '`/data` 디스크에 있는 파일을 `/home` 디스크 쪽 경로에서도 접근하게 하고 싶습니다. 두 곳은 **서로 다른 파일 시스템** 입니다. 어떤 링크를 써야 할까요?', '하드 링크는 같은 inode 에 이름을 붙이는 것이라는 점을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["하드 링크 (파일 시스템이 달라도 같은 inode 를 공유한다)", "심볼릭 링크 (경로를 가리키므로 파일 시스템이 달라도 된다)", "둘 다 불가능하다 (링크는 같은 디렉터리 안에서만 만들 수 있다)", "링크 대신 `cp -l` 만 가능하다 (심볼릭 링크는 다른 파일 시스템을 가리킬 수 없다)"]', 1, '하드 링크는 inode 번호를 공유하는 이름이라서 **같은 파일 시스템 안에서만** 만들 수 있습니다. 심볼릭 링크는 경로 글자를 담은 별도의 파일이라 다른 파일 시스템의 경로도 가리킬 수 있습니다.', NULL, NULL, NULL, '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 11, '심볼릭 링크 만들기', '대상을 가리키는 **심볼릭 링크** 를 만드는 `ln` 옵션을 채우세요.', '심볼릭(symbolic)의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-s", "-l", "-x", "-k"]', NULL, '`ln -s 대상 링크이름` 이 심볼릭 링크를 만듭니다. `-s` 없이 `ln 원본 새이름` 만 쓰면 하드 링크가 됩니다. `-l`·`-x`·`-k` 는 `ln` 에 이런 뜻으로 쓰는 옵션이 아닙니다.', '[0]', 'ln {0} /tmp/lab/app/config.txt /tmp/lab/current.conf', NULL, '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]'),
  (370, 12, '패치 만들어 적용하는 흐름', '옛 파일을 새 파일과 같게 바꾸는 패치를 만들고 적용해 확인하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 확인 → 적용 → 검증 순서예요.', NULL, NULL, '[]', 'order', '["`diff -u 옛파일 새파일 > 패치` 로 패치 파일을 만든다", "`cat 패치` 로 변경 내용을 확인한다", "`patch 옛파일 < 패치` 로 적용한다", "`cmp 옛파일 새파일` 로 같아졌는지 확인한다"]', NULL, '`diff -u` 로 변경 내용을 패치 파일로 만들고, 내용을 눈으로 확인한 뒤 `patch` 로 적용하고, 마지막에 `cmp` 나 `diff` 로 정말 같아졌는지 검증합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "ln 설명서", "url": "https://manpages.debian.org/bookworm/coreutils/ln.1.en.html"}, {"title": "symlink(7) 심볼릭 링크", "url": "https://man7.org/linux/man-pages/man7/symlink.7.html"}, {"title": "inode(7) 아이노드", "url": "https://man7.org/linux/man-pages/man7/inode.7.html"}, {"title": "diff 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/diff.1.en.html"}, {"title": "patch 설명서", "url": "https://manpages.debian.org/bookworm/patch/patch.1.en.html"}, {"title": "cmp 설명서", "url": "https://manpages.debian.org/bookworm/diffutils/cmp.1.en.html"}]');
